Given an array arr[] consisting of distinct integers, check if the given array can represent preorder traversal of a BST.Examples:Input:  arr[] = [40, 30, 35, 80, 100]Output: trueExplanation: Given array can represent preorder traversal of below tree Input: arr[] = [2, 4, 3]Output: trueExplanation: Given arr[] can represent preorder traversal of following BST: Try It YourselfTable of Content[Naive approach] First Greater Element - O(n ^ 2) Time and O(n) Space[Expected Approach - 1] Using Stack - O(n) Time and O(n) Space[Expected Approach - 2] Pass Range in Recursion  - O(n) Time and O(n) Space[Naive approach] First Greater Element - O(n ^ 2) Time and O(n) SpaceThe idea is to treat the first element as the root, find the first greater element which separates the left and right subtrees, and verify that all elements in the right subtree are greater than the root. Recursively apply the same check to the left and right subarrays.For example in [40, 30, 35, 80, 100], 40 is the first element, so we make it root. Now we look for the first element greater than 40, we find 80. So we know the structure of BST is as follows: 
            C++

    #include <bits/stdc++.h>
using namespace std;

bool check(vector<int> &arr, int l, int r)
{

    // If subtree has 0 or 1 node
    if (l >= r)
        return true;

    int j = l + 1;

    // Find first element greater than root
    while (j <= r && arr[j] < arr[l])
        j++;

    // Check whether all elements in right subtree
    // are greater than root
    for (int k = j; k <= r; k++)
    {
        if (arr[k] < arr[l])
            return false;
    }

    // Recursively check left and right subtrees
    return check(arr, l + 1, j - 1) && check(arr, j, r);
}

bool canRepresentBST(vector<int> &arr)
{

    return check(arr, 0, arr.size() - 1);
}

// Driver Code
int main()
{

    vector<int> arr = {40, 30, 35, 80, 100};

    if (canRepresentBST(arr))
        cout << "true\n";
    else
        cout << "false\n";

    return 0;
}


